# Column-coordinate homogeneous composition and noncommuting distractor, default Python only.
def mv(A,x):return [sum(a*v for a,v in zip(row,x)) for row in A]
def mm(A,B):return [[sum(A[i][k]*B[k][j] for k in range(3)) for j in range(3)] for i in range(3)]
A=[[0.,-1.,2.],[1.,0.,1.],[0.,0.,1.]];B=[[1.,0.,3.],[0.,1.,4.],[0.,0.,1.]];p=[1.,2.,1.]
check('transform-composition',mv(mm(A,B),p)==mv(A,mv(B,p))==[-4.,5.,1.],'T_map,odom multiplied on the left of T_odom,base')
check('reverse-order-differs',mv(mm(B,A),p)!=mv(mm(A,B),p),'Reverse product maps this point to a different position')
rng=random.Random(5916)
for i in range(1000):
 z=rng.uniform(.1,10);fx=rng.uniform(100,1000);fy=rng.uniform(100,1000);u=rng.uniform(-200,1000);v=rng.uniform(-200,1000);cx=rng.uniform(0,640);cy=rng.uniform(0,480);X=(u-cx)*z/fx;Y=(v-cy)*z/fy
 assert abs(fx*X/z+cx-u)<1e-9 and abs(fy*Y/z+cy-v)<1e-9
checks.append({'name':'pinhole-projection-roundtrip-1000','passed':True,'detail':'1000 seeded positive-depth/focal-length cases; algebraic exercise only, not camera API execution.'})
